function validate([words, chars]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 1000) return 'words needs 1 to 1000 strings.';
  if (words.some(w => typeof w !== 'string' || !/^[a-z]{1,100}$/.test(w))) return 'Each word is 1 to 100 lowercase letters.';
  if (typeof chars !== 'string' || !/^[a-z]{1,100}$/.test(chars)) return 'chars is 1 to 100 lowercase letters.';
  return null;
}

