function countCharacters(words, chars) {
  // Physically remove one matching tile per letter from a fresh copy of the supply.
  let total = 0;
  for (const word of words) {
    const tiles = chars.split('');
    let ok = true;
    for (const letter of word) {
      const at = tiles.indexOf(letter);
      if (at === -1) { ok = false; break; }
      tiles.splice(at, 1);
    }
    if (ok) total += word.length;
  }
  return total;
}

