function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const randomText = (length, alphabet) => Array.from({ length }, () => alphabet[Math.floor(rand() * alphabet.length)]).join('');
  if (size === 'large') {
    const alphabet = letters.slice(0, 3 + Math.floor(rand() * 24));
    const chars = randomText(100, alphabet);
    const words = Array.from({ length: 1000 }, () => {
      const length = 1 + Math.floor(rand() * 100);
      if (rand() < 0.5) return randomText(Math.min(length, 12), alphabet);
      // Build a word from a shuffled copy of the supply so many words are good.
      const tiles = chars.split('');
      for (let i = tiles.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [tiles[i], tiles[j]] = [tiles[j], tiles[i]]; }
      const word = tiles.slice(0, length).join('');
      return rand() < 0.3 && word.length < 100 ? word + alphabet[Math.floor(rand() * alphabet.length)] : word;
    });
    return [words, chars];
  }
  const alphabet = letters.slice(0, 2 + Math.floor(rand() * 3));
  const chars = randomText(1 + Math.floor(rand() * 7), alphabet);
  const words = Array.from({ length: 1 + Math.floor(rand() * 5) }, () => randomText(1 + Math.floor(rand() * 5), alphabet));
  return [words, chars];
}
